// Alerta interna al admin por cada turno vencido sin atender.
// El backend solo devuelve turnos SIN alerta previa registrada... no:
// devuelve todos los vencidos; la desduplicación se hace aquí consultando
// una sola vez por ejecución y alertando en lote (un mensaje por corrida).
const { items, count } = $input.first().json;
if (!count) {
  return []; // nada vencido: la ejecución termina sin enviar mensajes
}
const lines = items.map((entry) => {
  const appt = entry.appointment;
  return `#${appt.daily_number} ${appt.time_local} ${appt.customer_name} (${appt.barber.name})`;
});
const tenant = items[0].tenant;
const text = `Posibles no-show (${count}): ${lines.join(' | ')}. Márcalos en el panel: en curso, completado o no asistió.`;
return [{
  json: {
    waPayload: {
      messaging_product: 'whatsapp',
      to: tenant.whatsapp_number,
      type: 'template',
      template: {
        name: 'notificacion_interna',
        language: { code: 'es_CO' },
        components: [
          { type: 'body', parameters: [{ type: 'text', text }] },
        ],
      },
    },
  },
}];
